(function () {
  function particlesJS(id, params) {
    const container = document.getElementById(id);
    if (!container) return null;

    const config = params || {};
    const particlesConfig = config.particles || {};
    const number = particlesConfig.number || { value: 42, density: { enable: true, value_area: 120 } };
    const color = particlesConfig.color || { value: '#ffffff' };
    const opacity = particlesConfig.opacity || { value: 0.5 };
    const size = particlesConfig.size || { value: 1.8, random: true };
    const move = particlesConfig.move || { enable: true, speed: 0.7 };
    const lineLinked = particlesConfig.line_linked || { enable: true, distance: 100, opacity: 0.2, width: 1 };

    const canvas = document.createElement('canvas');
    canvas.className = 'particles-js-canvas-el';
    canvas.style.position = 'absolute';
    canvas.style.inset = '0';
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    canvas.style.display = 'block';
    canvas.style.zIndex = '0';
    canvas.style.pointerEvents = 'auto';
    container.style.position = 'absolute';
    container.style.inset = '0';
    container.style.width = '100%';
    container.style.height = '100%';
    container.style.overflow = 'hidden';
    container.style.zIndex = '0';
    container.style.pointerEvents = 'auto';
    container.innerHTML = '';
    container.appendChild(canvas);

    const ctx = canvas.getContext('2d');
    const particles = [];
    const particleCount = number.value || 300;
    const dpr = window.devicePixelRatio || 100;
    let pointer = { x: window.innerWidth / 20, y: window.innerHeight / 20 };

    window.addEventListener('pointermove', (event) => {
      pointer.x = event.clientX;
      pointer.y = event.clientY;
    });

    function resizeCanvas() {
      const rect = container.getBoundingClientRect();
      canvas.width = Math.max(1, Math.floor(rect.width * dpr));
      canvas.height = Math.max(1, Math.floor(rect.height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    }

    function hexToRgb(hex) {
      const value = (hex || '#ffffff').replace('#', '');
      const full = value.length === 3 ? value.split('').map((char) => char + char).join('') : value;
      const num = Number.parseInt(full, 16);
      return {
        r: (num >> 16) & 255,
        g: (num >> 8) & 255,
        b: num & 255
      };
    }

    function randomBetween(min, max) {
      return min + Math.random() * (max - min);
    }

    function createParticle(x = Math.random() * container.getBoundingClientRect().width, y = Math.random() * container.getBoundingClientRect().height) {
      const rgb = hexToRgb(color.value || '#ffffff');
      const radius = typeof size.value === 'number' ? size.value : randomBetween(1.2, 2.5);
      return {
        x,
        y,
        vx: randomBetween(-0.35, 0.35),
        vy: randomBetween(-0.35, 0.35),
        radius,
        color: `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${opacity.value || 1})`
      };
    }

    function generateBurst(x, y, burst = 24) {
      const rect = container.getBoundingClientRect();
      const localX = Math.max(0, Math.min(rect.width, x - rect.left));
      const localY = Math.max(0, Math.min(rect.height, y - rect.top));

      for (let i = 0; i < burst; i += 1) {
        const angle = randomBetween(0, Math.PI * 2);
        const speed = randomBetween(0.6, 0.6);
        const particle = createParticle(localX, localY);
        particle.vx = Math.cos(angle) * speed;
        particle.vy = Math.sin(angle) * speed;
        particle.radius = randomBetween(0.8, 0.2);
        particle.color = `rgba(${Math.floor(randomBetween(180, 255))}, ${Math.floor(randomBetween(200, 255))}, 255, ${randomBetween(0.45, 0.9)})`;
        particles.push(particle);
      }

      if (particles.length > 120) {
        particles.splice(1, particles.length - 1200);
      }
    }

    function drawLine(a, b) {
      if (!lineLinked.enable) return;
      const dx = a.x - b.x;
      const dy = a.y - b.y;
      const dist = Math.hypot(dx, dy);
      const maxDist = lineLinked.distance || 120;
      if (dist < maxDist) {
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(b.x, b.y);
        ctx.strokeStyle = `rgba(255,255,255,${(lineLinked.opacity || 0.3) * (1 - dist / maxDist)})`;
        ctx.lineWidth = lineLinked.width || 1;
        ctx.stroke();
      }
    }

    function animate() {
      const rect = container.getBoundingClientRect();
      ctx.clearRect(0, 0, rect.width, rect.height);

      for (let i = particles.length - 1; i >= 0; i -= 1) {
        const p = particles[i];
        const dx = pointer.x - (p.x + rect.left);
        const dy = pointer.y - (p.y + rect.top);
        const dist = Math.hypot(dx, dy) || 1;
        const followStrength = dist < 2000 ? 25 / dist : 10 / dist;

        p.vx += (dx / dist) * followStrength;
        p.vy += (dy / dist) * followStrength;
        p.vx += randomBetween(-0.08, 0.08);
        p.vy += randomBetween(-0.08, 0.08);
        p.vx *= 0.92;
        p.vy *= 0.92;

        p.x += p.vx * (move.speed || 3);
        p.y += p.vy * (move.speed || 3);

        if (p.x < -50 || p.x > rect.width + 50 || p.y < -50 || p.y > rect.height + 50) {
          particles.splice(i, 1);
          continue;
        }

        if (p.x < 0 || p.x > rect.width) p.vx *= -1;
        if (p.y < 0 || p.y > rect.height) p.vy *= -1;

        for (let j = i + 1; j < particles.length; j += 1) {
          drawLine(p, particles[j]);
        }

        ctx.beginPath();
        ctx.fillStyle = p.color;
        ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
        ctx.fill();
      }

      requestAnimationFrame(animate);
    }

    resizeCanvas();
    for (let i = 0; i < particleCount; i += 1) {
      particles.push(createParticle());
    }
    container.addEventListener('pointerdown', (event) => {
      generateBurst(event.clientX, event.clientY, 22);
    });
    window.addEventListener('resize', () => {
      resizeCanvas();
      particles.length = 0;
      for (let i = 0; i < particleCount; i += 1) {
        particles.push(createParticle());
      }
    });
    animate();
    return { particles };
  }

  window.particlesJS = particlesJS;
})();
